using System.Globalization;
using System.Net;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Mvc;

namespace BeautyBookBackend.Services;

// Only escaped public projections enter this template; the script is static and hash-allowed by CSP.
public static class SharedPageRenderer
{
    private static string E(string? value) => WebUtility.HtmlEncode(value ?? "");
    private const string Store = "https://play.google.com/store/apps/details?id=com.bbook.app";
    private static string Icon(string name) => "<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">" + (name switch {
        "back" => "<path d=\"m14 6-6 6 6 6\"/>",
        "share" => "<circle cx=\"18\" cy=\"5\" r=\"3\"/><circle cx=\"6\" cy=\"12\" r=\"3\"/><circle cx=\"18\" cy=\"19\" r=\"3\"/><path d=\"m9 10 6-4M9 14l6 4\"/>",
        "pin" => "<path d=\"M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z\"/><circle cx=\"12\" cy=\"10\" r=\"2.5\"/>",
        "calendar" => "<rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"3\"/><path d=\"M7 3v5m10-5v5M3 11h18m-14 5h2m6 0h2\"/>",
        "users" => "<circle cx=\"9\" cy=\"8\" r=\"4\"/><path d=\"M2 21v-2a7 7 0 0 1 14 0v2m1-18a4 4 0 0 1 0 8m3 10v-2a7 7 0 0 0-3-6\"/>",
        "star" => "<path d=\"m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1Z\"/>",
        "heart" => "<path d=\"M20 4a6 6 0 0 0-8 2 6 6 0 0 0-8-2c-5 4-1 10 8 17 9-7 13-13 8-17Z\"/>",
        "image" => "<rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"3\"/><circle cx=\"8\" cy=\"8\" r=\"1\"/><path d=\"m3 17 6-6 4 4 3-3 5 5\"/>",
        "brush" => "<path d=\"m13 13 8-9a2 2 0 0 0-3-3l-8 9m0 0 3 3c-1 7-7 9-11 8 4-2 1-8 8-11Z\"/>",
        _ => "<path d=\"m9 5 7 7-7 7\"/>"
    }) + "</svg>";
    private static string Navigation => $"<nav aria-label=\"Điều hướng\"><a class=\"round\" href=\"https://bbookmakeup.com\" aria-label=\"Trang chủ BBook\">{Icon("back")}</a><div class=\"nav-actions\"><button class=\"share\" type=\"button\" data-share>{Icon("share")} Chia sẻ</button><details class=\"menu\"><summary class=\"round\" aria-label=\"Tùy chọn chia sẻ\">•••</summary><div><button type=\"button\" data-copy>Sao chép liên kết</button><a href=\"https://bbookmakeup.com\">Về trang chủ BBook</a></div></details></div></nav>";
    private static string Actions(string app) => $"<div class=\"actions\"><a class=\"button\" href=\"{E(app)}\">{Icon("calendar")}Mở trong BBook</a><a class=\"button store\" href=\"{Store}\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 26\"><path fill=\"#31d0c4\" d=\"M1 1 14 13 1 25Z\"/><path fill=\"#37a6f4\" d=\"m1 1 16 9-3 3Z\"/><path fill=\"#ffd451\" d=\"m17 10 6 3-6 3-3-3Z\"/><path fill=\"#f4547b\" d=\"m1 25 13-12 3 3Z\"/></svg><span>Tải BBook<br>trên Google Play</span></a></div>";
    private static string Stat(string icon, string value, string label) => $"<div class=\"stat\"><span class=\"stat-icon\">{Icon(icon)}</span><div><strong>{E(value)}</strong><small>{E(label)}</small></div></div>";
    public static string Profile(SharedProfile? p)
    {
        if (p == null) return Unavailable(false);
        var app = $"bbookapp://mua-detail?id={p.MuaId:D}";
        var services = string.Join("", p.Services.Select(s => $"<a class=\"service\" href=\"{app}&amp;serviceId={s.Id:D}&amp;tab=D%E1%BB%8Bch%20v%E1%BB%A5\">{(s.ImageUrl == null ? $"<span class=\"service-placeholder\">{Icon("brush")}</span>" : $"<img loading=\"lazy\" src=\"{E(s.ImageUrl)}\" alt=\"\">")}<div><h3>{E(s.Name)}</h3><p>{s.Price.ToString("N0", CultureInfo.GetCultureInfo("vi-VN"))}đ · {s.DurationMinutes} phút</p><span class=\"next\">{Icon("next")}</span></div></a>"));
        var gallery = p.Works.Count > 0
            ? string.Join("", p.Works.Select(w => $"<a href=\"https://bbookmakeup.com/posts/{w.Id:D}\" aria-label=\"Xem bài viết của {E(p.Name)}\"><img loading=\"lazy\" src=\"{E(w.ImageUrl)}\" alt=\"Tác phẩm makeup của {E(p.Name)}\"></a>"))
            : string.Join("", p.Images.Select(image => $"<a href=\"{app}\"><img loading=\"lazy\" src=\"{E(image)}\" alt=\"Tác phẩm makeup\"></a>"));
        var content = $"""
            {Navigation}<header class="hero"><div class="portrait">{(p.AvatarUrl == null ? "<span class=\"avatar avatar-empty\">B</span>" : $"<img class=\"avatar\" src=\"{E(p.AvatarUrl)}\" alt=\"Ảnh đại diện {E(p.Name)}\">")}<span class="verified" title="Hồ sơ đã xác minh" aria-label="Hồ sơ đã xác minh">✓</span></div><div class="identity"><p class="brand">BBOOK · MAKEUP ARTIST</p><h1>{E(p.Name)}</h1>{(string.IsNullOrWhiteSpace(p.City) ? "" : $"<p class=\"location\">{Icon("pin")}{E(p.City)}</p>")}<div class="tags">{string.Join("", p.Specializations.Select(s => $"<span>{E(s)}</span>"))}</div></div></header>
            {(string.IsNullOrWhiteSpace(p.Bio) ? "" : $"<p class=\"bio\">{E(p.Bio)}</p>")}{Actions(app)}
            <div class="stats">{Stat("star", p.ReviewCount == 0 ? "Chưa có" : p.AverageRating.ToString("0.0", CultureInfo.InvariantCulture), $"Đánh giá ({p.ReviewCount})")}{Stat("users", p.CompletedCustomers.ToString(), "Khách hoàn tất")}{Stat("heart", p.ExperienceYears == 0 ? "Chưa cập nhật" : $"{p.ExperienceYears} năm", "Kinh nghiệm")}{Stat("pin", string.IsNullOrWhiteSpace(p.City) ? "Chưa cập nhật" : p.City, "Khu vực làm việc")}</div>
            <section id="services"><div class="section-heading"><h2>{Icon("brush")}Dịch vụ</h2><a href="{app}&amp;tab=D%E1%BB%8Bch%20v%E1%BB%A5">Xem trong app {Icon("next")}</a></div>{(p.Services.Count == 0 ? "<p class=\"empty\">Chuyên gia chưa có dịch vụ công khai.</p>" : $"<div class=\"services\">{services}</div>")}</section>
            <section id="portfolio"><div class="section-heading"><h2>{Icon("image")}Portfolio</h2><a href="{app}">Xem tất cả {Icon("next")}</a></div>{(gallery.Length == 0 ? "<p class=\"empty\">Chưa có tác phẩm công khai.</p>" : $"<div class=\"gallery\">{gallery}</div>")}</section>
            <a class="invite" href="{app}">{Icon("heart")}<span>Mở BBook để theo dõi, nhắn tin và đặt lịch với chuyên gia.</span>{Icon("next")}</a><a class="button booking" href="{app}">{Icon("calendar")}Đặt lịch makeup</a><p class="hint">Chưa có ứng dụng? Tải BBook rồi mở lại liên kết này để xem đúng chuyên gia.</p>
            """;
        return Document($"{p.Name} · Chuyên gia makeup trên BBook", p.Bio, p.Url, p.AvatarUrl ?? p.Images.FirstOrDefault(), content, "profile");
    }
    public static string Post(SharedPost? p)
    {
        if (p == null) return Unavailable(true);
        var app = $"bbookapp://shared-post?id={p.Id:D}";
        var content = $"""
            {Navigation}<p class="brand">BBOOK · TÁC PHẨM MAKEUP</p><a class="post-author" href="https://bbookmakeup.com/mua/{p.MuaId:D}">{(p.AvatarUrl == null ? "<span class=\"mini-avatar avatar-empty\">B</span>" : $"<img class=\"mini-avatar\" src=\"{E(p.AvatarUrl)}\" alt=\"\">")}<div><strong>{E(p.Name)}</strong><small>{E(p.City)}</small></div>{Icon("next")}</a><h1 class="post-title">{E(string.IsNullOrWhiteSpace(p.Title) ? $"Tác phẩm của {p.Name}" : p.Title)}</h1><p class="bio">{E(p.Description)}</p><div class="tags">{string.Join("", p.Tags.Select(t => $"<span>{E(t)}</span>"))}</div><div class="post-images">{string.Join("", p.Images.Select((image, i) => $"<img {(i > 0 ? "loading=\"lazy\"" : "")} src=\"{E(image)}\" alt=\"Ảnh tác phẩm {i + 1} của {E(p.Name)}\">"))}</div>{Actions(app)}<a class="invite" href="https://bbookmakeup.com/mua/{p.MuaId:D}">{Icon("users")}<span>Xem hồ sơ và dịch vụ của {E(p.Name)}</span>{Icon("next")}</a><p class="hint">Chưa có ứng dụng? Tải BBook rồi mở lại liên kết để xem đúng bài viết.</p>
            """;
        return Document($"{(string.IsNullOrWhiteSpace(p.Title) ? "Tác phẩm makeup" : p.Title)} · {p.Name} · BBook", p.Description, p.Url, p.Images.FirstOrDefault() ?? p.AvatarUrl, content, "article");
    }
    private static string Unavailable(bool post) => Document($"{(post ? "Bài viết" : "Hồ sơ")} không khả dụng · BBook", "Nội dung chưa công khai hoặc không còn hoạt động.", null, null,
        $"{Navigation}<div class=\"unavailable\">{Icon("heart")}<h1>{(post ? "Bài viết" : "Hồ sơ")} không khả dụng</h1><p>Nội dung chưa công khai hoặc không còn hoạt động.</p><a class=\"button\" href=\"{Store}\">Tải BBook trên Google Play</a></div>", "website");
    private static string Document(string title, string? description, string? url, string? image, string content, string type)
    {
        description = string.IsNullOrWhiteSpace(description) ? "Khám phá Portfolio và đặt lịch makeup cùng BBook." : description;
        if (description.Length > 240) description = description[..240];
        var meta = url == null ? "<meta name=\"robots\" content=\"noindex\">" : $"<link rel=\"canonical\" href=\"{E(url)}\"><meta property=\"og:url\" content=\"{E(url)}\"><meta property=\"og:image\" content=\"{E(image ?? "https://bbookmakeup.com/assets/images/bbook-logo.png")}\">";
        return $$"""
            <!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#fff7fa"><title>{{E(title)}}</title><meta name="description" content="{{E(description)}}"><meta property="og:title" content="{{E(title)}}"><meta property="og:description" content="{{E(description)}}"><meta property="og:type" content="{{type}}">{{meta}}<style>{{Css}} {{MenuCss}}</style></head><body><main>{{content}}<div class="share-fallback" hidden><label for="share-url">Liên kết chia sẻ</label><input id="share-url" readonly><button type="button" data-copy>Sao chép liên kết</button></div><p id="share-notice" role="status" aria-live="polite"></p><footer><a href="https://bbookmakeup.com">BBook · Đặt lịch makeup theo cách của bạn</a></footer></main><script>{{Script}}</script></body></html>
            """;
    }
    public static ContentResult Response(HttpResponse response, string html, bool available)
    {
        var hash = Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(Script)));
        response.Headers["Content-Security-Policy"] = $"default-src 'none'; img-src https:; style-src 'unsafe-inline'; script-src 'sha256-{hash}'; base-uri 'none'; frame-ancestors 'none'; form-action 'none'";
        response.Headers["X-Content-Type-Options"] = "nosniff";
        response.Headers["Referrer-Policy"] = "no-referrer";
        return new ContentResult { Content = html, ContentType = "text/html; charset=utf-8", StatusCode = available ? 200 : 404 };
    }
    public const string Script = """
        (()=>{const url=document.querySelector('link[rel="canonical"]')?.href;const notice=document.getElementById('share-notice');const fallback=document.querySelector('.share-fallback');const input=document.getElementById('share-url');let busy=false;const copy=async()=>{if(!url)return;document.querySelectorAll('.menu').forEach(menu=>menu.open=false);try{if(!navigator.clipboard?.writeText)throw Error();await navigator.clipboard.writeText(url);notice.textContent='Đã sao chép liên kết';}catch{fallback.hidden=false;input.value=url;input.focus();input.select();notice.textContent='Nhấn giữ liên kết để sao chép và chia sẻ.';}};document.querySelectorAll('[data-share]').forEach(button=>{button.hidden=!url;button.addEventListener('click',async()=>{if(busy||!url)return;busy=true;button.disabled=true;try{if(navigator.share)await navigator.share({title:document.title,url});else await copy();}catch(error){if(error.name!=='AbortError')await copy();}finally{busy=false;button.disabled=false;}});});document.querySelectorAll('[data-copy]').forEach(button=>{button.hidden=!url;button.addEventListener('click',copy);});})();
        """;
    private const string MenuCss = """
        .nav-actions{display:flex;align-items:center;gap:10px}.menu{position:relative}.menu summary{list-style:none;cursor:pointer;font-size:20px;letter-spacing:1px}.menu summary::-webkit-details-marker{display:none}.menu>div{position:absolute;right:0;top:58px;z-index:4;width:220px;padding:8px;background:white;border:1px solid var(--line);border-radius:16px;box-shadow:0 12px 35px #59213618}.menu button,.menu a{display:block;width:100%;border:0;background:white;color:#9f1d56;text-align:left;padding:13px;border-radius:10px;font-size:14px}.menu button:hover,.menu a:hover{background:#fff1f7}@media(max-width:600px){.service{display:grid;grid-template-columns:40% minmax(0,1fr);min-height:115px}.service>img,.service-placeholder{height:100%;aspect-ratio:auto}.service h3{font-size:12px}.service p{font-size:10px}.service>div{padding:13px 9px 40px}.menu>div{top:50px}}
        """;
