display:flex;gap:8px;flex-wrap:wrap}.tags span{background:#ffe3ef;color:#cb236a;padding:6px 12px;border-radius:99px;font-size:13px}.bio{white-space:pre-wrap;overflow-wrap:anywhere;color:var(--muted);font-size:19px;margin:24px 0}.actions{display:grid;grid-template-columns:1.35fr 1fr;gap:16px;margin:24px 0}.button{display:flex;align-items:center;justify-content:center;gap:13px;min-height:72px;padding:14px 22px;border-radius:22px;background:linear-gradient(115deg,#ad205d,#b52265);color:white;font-weight:750;font-size:19px;line-height:1.3;text-align:center}.button svg{width:29px;height:29px}.store{background:#fae9f0;color:#9f1d56;font-size:17px;gap:16px}.store svg{width:31px;height:35px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid var(--line);border-radius:24px;padding:24px 12px;margin:24px 0 38px}.stat{display:flex;align-items:center;justify-content:center;gap:9px;padding:0 10px;min-width:0;border-right:1px solid var(--line)}.stat:last-child{border:0}.stat-icon{display:flex;padding:9px;background:#ffe5ef;border-radius:50%;color:var(--pink)}.stat strong{display:block;font-size:15px;line-height:1.3;overflow-wrap:anywhere}.stat small{display:block;color:var(--muted);font-size:12px;margin-top:4px}.section-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:30px 0 18px}h2{display:flex;align-items:center;gap:14px;font-size:25px;letter-spacing:-.6px;margin:0}.section-heading h2 svg{color:var(--pink);width:29px;height:29px}.section-heading>a{display:flex;align-items:center;gap:5px;font-size:14px;font-weight:700;color:#ca216b}.section-heading>a svg{width:18px}.services{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.service{display:grid;grid-template-columns:40% minmax(0,1fr);background:white;border:1px solid #f0e9ed;border-radius:23px;overflow:hidden;min-height:148px}.service>img,.service-placeholder{width:100%;height:100%;object-fit:cover}.service-placeholder{display:grid;place-items: