padding:16px 13px;gap:10px;border-radius:18px;margin-top:22px}.invite>svg{width:22px}.booking{border-radius:99px;font-size:17px;margin-top:18px}.hint{font-size:11px}.post-title{font-size:26px}.post-images{gap:10px}.post-images img{border-radius:16px}}@media(prefers-reduced-motion:reduce){.gallery img{transition:none}}
